j=0.725/A.XH(k,0.2)
i=[A.XH(l*q[0]*97.555292473/100,0.42),A.XH(l*q[1]*101.64689848600003/100,0.42),A.XH(l*q[2]*108.47692442799999/100,0.42)]
h=i[0]
